SELECT p.gender, p.age, a.admission_type_id, d.diagnosis_id, COUNT(a.hadm_id) AS count_admissions, SUM(CASE WHEN d.diagnosis_id IN (1010, 1011) THEN 1 ELSE 0 END) AS chest_pain_or_ami_count, SUM(CASE WHEN d.diagnosis_id IN (1010, 1011) THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(a.hadm_id), 0) AS proportion_chest_pain_or_ami, AVG(i.los) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN icustays i ON a.stay_id = i.stay_id WHERE p.gender = 'F' AND p.age BETWEEN 81 AND 91 AND a.admission_type_id IN (10, 11) AND d.diagnosis_id IN (1010, 1011) GROUP BY p.gender, p.age, a.admission_type_id, d.diagnosis_id ORDER BY p.gender, p.age, a.admission_type_id, d.diagnosis_id NULLS LAST;